const updateTask = `-- name: UpdateTask :one
UPDATE tasks
SET
    module_id = CASE WHEN $1::boolean THEN $2 ELSE module_id END,
    parent_id = CASE WHEN $3::boolean THEN $4 ELSE parent_id END,
    title = CASE WHEN $5::boolean THEN $6 ELSE title END,
    description = CASE WHEN $7::boolean THEN NULLIF($8, '') ELSE description END,
    status = CASE WHEN $9::boolean THEN NULLIF($10, '')::task_status ELSE status END,
    priority = CASE WHEN $11::boolean THEN $12 ELSE priority END,
    start_date = CASE WHEN $13::boolean THEN $14 ELSE start_date END,
    end_date = CASE WHEN $15::boolean THEN $16 ELSE end_date END,
    first_completed_at = CASE
        WHEN first_completed_at IS NULL
         AND $9::boolean
         AND NULLIF($10, '')::task_status IN ('review', 'done')
         AND status NOT IN ('review', 'done')
        THEN NOW()
        ELSE first_completed_at
    END,
    estimation = CASE WHEN $17::boolean THEN $18 ELSE estimation END,
    archived = CASE WHEN $19::boolean THEN $20 ELSE archived END,
    return_count = CASE WHEN $21::boolean THEN $22 ELSE return_count END,
    fault_holder_id = CASE WHEN $23::boolean THEN $24 ELSE fault_holder_id END
WHERE id = $25 AND deleted_at IS NULL
RETURNING id, created_at, updated_at, deleted_at, project_id, module_id, created_by_id, parent_id,
          title, description, status, priority, start_date, end_date, first_completed_at, estimation, archived, return_count, fault_holder_id, sequence_no
`

type UpdateTaskParams struct {
	ModuleIDPresent      bool               `json:"module_id_present"`
	ModuleID             pgtype.UUID        `json:"module_id"`
	ParentIDPresent      bool               `json:"parent_id_present"`
	ParentID             pgtype.UUID        `json:"parent_id"`
	TitlePresent         bool               `json:"title_present"`
	Title                string             `json:"title"`
	DescriptionPresent   bool               `json:"description_present"`
	Description          interface{}        `json:"description"`
	StatusPresent        bool               `json:"status_present"`
	Status               interface{}        `json:"status"`
	PriorityPresent      bool               `json:"priority_present"`
	Priority             int32              `json:"priority"`
	StartDatePresent     bool               `json:"start_date_present"`
	StartDate            pgtype.Timestamptz `json:"start_date"`
	EndDatePresent       bool               `json:"end_date_present"`
	EndDate              pgtype.Timestamptz `json:"end_date"`
	EstimationPresent    bool               `json:"estimation_present"`
	Estimation           int32              `json:"estimation"`
	ArchivedPresent      bool               `json:"archived_present"`
	Archived             bool               `json:"archived"`
	ReturnCountPresent   bool               `json:"return_count_present"`
	ReturnCount          int32              `json:"return_count"`
	FaultHolderIDPresent bool               `json:"fault_holder_id_present"`
	FaultHolderID        pgtype.UUID        `json:"fault_holder_id"`
	ID                   pgtype.UUID        `json:"id"`
}

type UpdateTaskRow struct {
	ID               pgtype.UUID        `json:"id"`
	CreatedAt        pgtype.Timestamptz `json:"created_at"`
	UpdatedAt        pgtype.Timestamptz `json:"updated_at"`
	DeletedAt        pgtype.Timestamptz `json:"deleted_at"`
	ProjectID        pgtype.UUID        `json:"project_id"`
	ModuleID         pgtype.UUID        `json:"module_id"`
	CreatedByID      pgtype.UUID        `json:"created_by_id"`
	ParentID         pgtype.UUID        `json:"parent_id"`
	Title            string             `json:"title"`
	Description      pgtype.Text        `json:"description"`
	Status           TaskStatus         `json:"status"`
	Priority         int32              `json:"priority"`
	StartDate        pgtype.Timestamptz `json:"start_date"`
	EndDate          pgtype.Timestamptz `json:"end_date"`
	FirstCompletedAt pgtype.Timestamptz `json:"first_completed_at"`
	Estimation       int32              `json:"estimation"`
	Archived         bool               `json:"archived"`
	ReturnCount      int32              `json:"return_count"`
	FaultHolderID    pgtype.UUID        `json:"fault_holder_id"`
	SequenceNo       int32              `json:"sequence_no"`
}

func (q *Queries) UpdateTask(ctx context.Context, arg UpdateTaskParams) (UpdateTaskRow, error) {
	row := q.db.QueryRow(ctx, updateTask,
		arg.ModuleIDPresent,
		arg.ModuleID,
		arg.ParentIDPresent,
		arg.ParentID,
		arg.TitlePresent,
		arg.Title,
		arg.DescriptionPresent,
		arg.Description,
		arg.StatusPresent,
		arg.Status,
		arg.PriorityPresent,
		arg.Priority,
		arg.StartDatePresent,
		arg.StartDate,
		arg.EndDatePresent,
		arg.EndDate,
		arg.EstimationPresent,
		arg.Estimation,
		arg.ArchivedPresent,
		arg.Archived,
		arg.ReturnCountPresent,
		arg.ReturnCount,
		arg.FaultHolderIDPresent,
		arg.FaultHolderID,
		arg.ID,
	)
	var i UpdateTaskRow
	err := row.Scan(
		&i.ID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.ProjectID,
		&i.ModuleID,
		&i.CreatedByID,
		&i.ParentID,
		&i.Title,
		&i.Description,
		&i.Status,
		&i.Priority,
		&i.StartDate,
		&i.EndDate,
		&i.FirstCompletedAt,
		&i.Estimation,
		&i.Archived,
		&i.ReturnCount,
		&i.FaultHolderID,
		&i.SequenceNo,
	)
	return i, err
}

